"""Build a portable Russian report from independently recounted evidence."""
import argparse
from html import escape
import json
from pathlib import Path

parser=argparse.ArgumentParser();parser.add_argument('analysis',type=Path);parser.add_argument('output',type=Path)
args=parser.parse_args();a=json.loads((args.analysis/'analysis.json').read_text());assert a['verification_consistent']
args.output.mkdir(parents=True,exist_ok=False)
names={'dense_original':'Исходная M0','dense_recovery':'Плотная + 200','fixed_prune':'Каналы 75%',
       'fixed_svd':'SVD 50% / лучший R','fixed_hybrid':'Каналы → SVD','evolution_finalist':'Лучший E'}
order={name:i for i,name in enumerate(names)}
rows=sorted(a['rows'],key=lambda row:min(order[role] for role in row['roles'] if role in order))
label=lambda row:' / '.join(names[role] for role in row['roles'] if role in names)
fmt=lambda value,n=2:f'{value:.{n}f}'.replace('.',',')
dense=next(row for row in rows if 'dense_recovery' in row['roles']);m0=next(row for row in rows if 'dense_original' in row['roles'])
svd=next(row for row in rows if 'fixed_svd' in row['roles']);evo=next(row for row in rows if 'evolution_finalist' in row['roles'])
aa=[]
for row in a['AA']:
    owner=next((value for value in rows if value['artifact_id']==row['label']),None)
    aa.append({**row,'name':'Начальный A/A M0' if row['label']=='initial_M0' else label(owner)})
intro='Продолжение завершило пять восстановлений и независимый тест шести артефактов. Исходный критерий выполнили 3 из 4 компактных моделей. Процедура 200 SGD + BN снизила качество самого плотного контроля; относительно исходной M0 потеря всех компактных моделей превышает 2 п.п. Допуск конечных измерений компактных моделей не пройден, ускорение не установлено.'
lines=['# A100: завершение Sparse/CV-пилота','', '[PR #140](https://github.com/v1docq/FedCore/pull/140) · ResNet18 / CIFAR-10 · 26.10.2026','',intro,'',
    '## Что выполнено','',
    f"Одно разрешённое продолжение заняло {fmt(a['completion_seconds']/60)} минуты при внешнем пределе 30 минут. С учётом двух прежних попыток — **{fmt(a['total_seconds']/60)} / 240 минут**. Исходная M0 не переобучалась, поиск не повторялся. Старые неуспешные отчёты не заменены успешными. Новые материалы имеют собственное происхождение и статус `completed`.", '',
    'Перед запуском отдельно проверены 176 файлов / 3 236 684 168 байт исходной инвентаризации. Для полного пространства исходных имён собрана новая копия `parent-snapshot`: в ней объединены веса и внешние журналы, исходные пути не менялись. Первая проверка, указывавшая непосредственно на старый `pilot-2`, выявила нехватку внешних журналов до CUDA; её лог сохранён. После подготовки полной копии окончательная проверка дала `prepared`. Это подготовка, без повторного численного запуска.','',
    'Новый установленный wheel проверил 314 файлов пакета; Linux CPU-серия — 84 passed. Ранее локально: расширенная серия 218 passed / 2 skipped, после замечаний — целевая 82 passed / 2 skipped. Сравнение зависимостей разрешает только замену wheel FedCore. M0 и её предсказания перенесены побайтно, новый проход по 5000 изображениям дал те же предсказания и потери.','',
    '## Качество и физическое хранение','',
    'Официальный тест содержит 10 000 изображений. До его открытия зафиксированы шесть полных артефактов и их хеши. Пять восстановлений получили одинаковую ленту по 200 обновлений SGD и одинаковую калибровку BatchNorm; все сборки начинались с полной M0. Лучший R совпал с фиксированным SVD и использовал один артефакт.','',
    '| Модель | Доля байтов M0 | Тензоры, MiB | Top-1 test | Δ к плотной +200, п.п. | Δ к M0, п.п. | Исходный критерий |',
    '| --- | ---: | ---: | ---: | ---: | ---: | --- |']
for row in rows:
    criterion=('да' if row['accepted'] else 'нет') if row['tensor_bytes']<44734408 else 'контроль, вне бюджета'
    lines.append(f"| {label(row)} | {fmt(100*row['fraction_M0'])}% | {fmt(row['tensor_bytes']/1048576)} | {fmt(100*row['top1'])}% | {fmt(row['delta_to_recovered_dense_pp'])} | {fmt(row['delta_to_M0_pp'])} | {criterion} |")
lines += ['',f"Исходный критерий — не более 80% байтов M0 и не более 2 п.п. потери к плотной модели после тех же 200 обновлений. Её точность — {fmt(100*dense['top1'])}%, порог качества — {fmt(100*(dense['top1']-.02))}%. Этот критерий не менялся после получения теста.",'',
    f"Плотная M0 дала {fmt(100*m0['top1'])}%; процедура восстановления снизила её качество на {fmt(100*(m0['top1']-dense['top1']))} п.п. Дополнительное описательное сравнение с M0 даёт порог {fmt(100*(m0['top1']-.02))}%, которому не отвечает ни один из четырёх компактных вариантов. Это диагностическое сравнение, а не новый отбор финалистов. Влияние SGD и повторной BN-калибровки по этому запуску раздельно не установлено.",'',
    'Калибровочные 1000 изображений, поисковые 5000 и обучающие 44 000 взяты из официальной обучающей части. Официальный тест не участвовал в выборе графов. Физические байты включают все тензоры модели, в том числе BatchNorm и неизменяемые части; размер файла учитывается отдельно.','',
    '## Что произошло с R/E после восстановления','',
    f"Короткий поиск выбирал E с поисковой точностью 94,06% против 93,78% у R. После одинакового восстановления на той же поисковой выборке R дал 92,20%, E — 91,88%. На независимом тесте R дал {fmt(100*svd['top1'])}%, E — {fmt(100*evo['top1'])}%; разность E−R — {fmt(100*(evo['top1']-svd['top1']))} п.п. при экономии {svd['tensor_bytes']-evo['tensor_bytes']} байт. В этой единственной паре короткое ранжирование не сохранилось. Причинного или статистического превосходства одного поиска это не доказывает.",'',
    '## Время GPU и A/A','',
    'Новый начальный A/A прошёл. Конечный A/A исходной M0 также прошёл. У всех трёх измеряемых компактных артефактов конечный A/A не прошёл полный профиль из пакетов 1 и 128; A/B для них не запускался. Единственный допущенный A/B — самосравнение M0, оно не является ускорением сжатой модели.','',
    '| Контроль | Пакет | Часы | Медиана B/A | В пределах ±15%, из 20 | Отношение медиан AB/BA | Допуск |',
    '| --- | ---: | --- | ---: | ---: | ---: | --- |']
for row in aa:
    lines.append(f"| {row['name']} | {row['batch']} | {row['clock']} | {fmt(row['median_ratio'],4)} | {row['inside_15_percent']} | {fmt(row['ab_ba_median_ratio'],4)} | {'да' if row['accepted'] else 'нет'} |")
lines += ['',
    'Контроль сравнивает два отдельно загруженных экземпляра одного артефакта. Порог медианы 0,95–1,05; не менее 18/20 отношений внутри 0,85–1,15; отношение медиан порядков 0,90–1,10. У SVD/R и E пакет 1 прошёл, пакет 128 — нет; исходный протокол требует весь профиль. Повторы для получения допуска не выполнялись.','',
    'При чтении кода обнаружено различие путей подготовки пары: первый экспорт возвращает TorchScript после загрузки на CPU и переноса на CUDA, независимая копия загружается сразу на CUDA. Для уже сохранённой M0 оба конечных экземпляра загружаются сразу на CUDA. Это проверяемая гипотеза о влиянии способа загрузки; связь с наблюдаемым сдвигом A/A ещё не подтверждена отдельным экспериментом.','',
    '## Проверка, ресурсы и пределы выводов','',
    f"Независимый пересчёт NumPy/стандартной библиотекой: **{a['checks']} согласованных проверок**, {a['prediction_files']} файлов / {a['prediction_rows']} строк. Из них 5000 строк — побайтно скопированные исходные предсказания M0, 90 000 — новые оценки продолжения. Проверены исходный выбор, общая лента SGD, шесть полных артефактов, физические байты по формулам и Torch ZIP-хранилищам, фиксация до теста, качество и допуски A/A. Модели повторно не исполнялись.",'',
    f"Максимумы PyTorch allocated/reserved — {fmt(a['peak_allocated_bytes']/1024**3)} / {fmt(a['peak_reserved_bytes']/1024**3)} GiB; максимум RSS внешнего наблюдателя — {fmt(a['peak_rss_bytes']/1024**3)} GiB. Это разные показатели; резерв PyTorch не равен всей памяти процесса GPU. Учтённый расход включает всё внешнее окно и завершение.",'',
    'Проверена одна обученная M0 и одна пара поисков с ограниченным меню внутренних каналов BasicBlock и SVD. Работоспособность общего графа и сквозного пути сохранения/загрузки подтверждена в этом профиле. Превосходство эволюции, ускорение, перенос на ImageNet или другие архитектуры и CUDA sparse/INT8-ядра не подтверждены. Общая issue #99 остаётся открытой.','',
    '## Следующие отдельные задачи','',
    '1. Разделить влияние BN-калибровки и SGD: проверить плотную модель без изменений, с одной BN-калибровкой, с восстановлением при меньшем шаге обучения и с обеими процедурами. До устранения падения плотного контроля не расширять сравнение поисков.\n2. Согласовать пути загрузки обоих экземпляров TorchScript и отдельно повторить A/A с заранее заданным протоколом. Только после допуска сравнивать скорость компактных моделей.\n3. После этих проверок планировать несколько исходных состояний поиска, затем CIFAR-100 и более сложные CV-сценарии. Новый бюджет согласуется отдельно; в этом продолжении дополнительных запусков не было.','',
    f"Исходники продолжения: `{a['source_commit']}`; wheel: `{a['wheel_sha256']}`. Численный протокол: `81e30bb6853080e2b6fedf966fc19f44cf717a8192988df5c3db552a3dd12010`.",'',
    '[HTML-отчёт](a100-completion-report.html) · [Исходный результат](results/a100-completion-2026-10-26/raw/report.json) · [Пересчёт](results/a100-completion-2026-10-26/analysis/analysis.json) · [Предыдущая попытка](A100_PILOT_2.md) · [Режим продолжения](IMPLEMENTATION_CV_COMPLETION.md).','']
(args.output/'A100_COMPLETION.md').write_text('\n'.join(lines),encoding='utf-8')
payload={'analysis':a,'rows':[{**row,'name':label(row)} for row in rows],'aa':aa}
template=(Path(__file__).with_name('completion-report.template.html')).read_text(encoding='utf-8')
(args.output/'a100-completion-report.html').write_text(template.replace('__DATA__',json.dumps(payload,ensure_ascii=False,allow_nan=False).replace('<','\\u003c')),encoding='utf-8')
print(json.dumps({'checks':a['checks'],'status':a['status'],'total_minutes':a['total_seconds']/60}))
